namespace Trackwise.DbMigrator.Models;

/// <summary>
/// A real truck from the company's vehicle register (Monday Admin &gt; SKYBEST VEHICLES), merged with
/// what only the Cold Chain boards carry (chassis/engine numbers, tonnage, standing driver). Seeded by
/// <c>FleetSeeder</c>; generated by <c>monday-export/scripts/fleet.py</c>.
/// </summary>
public record FleetTruckData
{
    /// <summary>The plate - also the truck's code, which is how dispatch boards name a unit.</summary>
    public required string Plate { get; set; }

    /// <summary>A <c>TruckType</c> name, e.g. <c>Reefer</c>, <c>WingVan</c>, <c>ContainerTruck</c> (tractor head).</summary>
    public string Type { get; set; } = "Reefer";

    /// <summary>A <c>TruckTonnageClass</c> name, or null for body types with no tonnage (tractor heads).</summary>
    public string? TonnageClass { get; set; }

    public string? Make { get; set; }
    public string? Model { get; set; }

    /// <summary>The chassis number, stored as the VIN - the identifier Philippine registrations carry.</summary>
    public string? ChassisNumber { get; set; }

    public string? EngineNumber { get; set; }
    public string? AssetCode { get; set; }
    public string? ConductionSticker { get; set; }
    public DateOnly? AcquiredOn { get; set; }
    public string? Supplier { get; set; }

    /// <summary>A <c>TruckOwnership</c> name, or null when unconfirmed.</summary>
    public string? Ownership { get; set; }

    /// <summary>Home branch code (<c>MNL</c>, <c>CEB</c>, <c>CGY</c>, <c>DVO</c>), or null when unknown or not a branch yet (Bacolod).</summary>
    public string? Branch { get; set; }

    /// <summary>
    /// Full name of a <c>Crew</c> driver, only where dispatch history shows a real standing
    /// assignment. Most units rotate among several drivers day to day and have none.
    /// </summary>
    public string? MainDriver { get; set; }

    /// <summary>False for units sold, for sale or scrapped.</summary>
    public bool IsActive { get; set; } = true;

    public VehiclePaperData[] Papers { get; set; } = [];
}
